-- Personal Finance and Stewardship final module. Run seed_pfs_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'personal-finance';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Personal Financial Plan$j$, $j${"prompt": "Create a complete personal financial plan in a report of at least 700 words. You may use your real situation or a realistic made up one. Do not include real account numbers, Social Security numbers, passwords or other private details, and ask a parent, guardian or teacher to review your plan. Include tables or lists for the numbers. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nPart 1: Stewardship and Goals. Explain what it means to be a steward. Write three SMART goals: one short term, one medium term and one long term.\nPart 2: Income and Taxes. Describe your income sources or expected career, and calculate gross pay, estimated deductions and net pay for one month using realistic numbers. Name the forms you would receive and file.\nPart 3: Monthly Budget. Build a zero based monthly budget that includes giving, saving, fixed expenses and variable expenses, and show that income minus expenses equals zero.\nPart 4: Saving and Banking. Design a plan for a starter emergency fund and then three to six months of expenses. Choose the type of account and explain how you will protect your money from fraud.\nPart 5: Credit and Debt. Explain how you will build and protect credit, and write a plan to avoid or pay off debt, including one loan example with principal, interest rate and term.\nPart 6: Investing and Retirement. Explain risk, return and diversification, and describe how you would begin investing for the long term, including an employer match or IRA.\nPart 7: Protection and Major Purchases. Choose the insurance you would need and explain why. Plan a major purchase such as a car, including the total cost of ownership.\nPart 8: Giving, Legacy and Faith. Explain your plan for giving, apply at least three Scripture passages from the King James Version, and write a legacy statement.", "rubric": "100 points. Part 1, stewardship and goals: 10 points. Part 2, income and taxes: 10 points. Part 3, monthly budget: 15 points. Part 4, saving and banking: 10 points. Part 5, credit and debt: 15 points. Part 6, investing and retirement: 10 points. Part 7, protection and major purchases: 10 points. Part 8, giving, legacy and faith: 15 points. Grammar, conventions and accurate math: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Personal Financial Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Personal Finance and Stewardship$j$, $j${"questions": [{"q": "A person who manages what belongs to another is a:", "options": ["Debtor", "Landlord", "Steward", "Beneficiary"]}, {"q": "Something required to live, such as basic food and shelter, is a:", "options": ["Want", "Gift", "Luxury", "Need"]}, {"q": "Pay after taxes and deductions is called:", "options": ["Principal", "Profit", "Gross pay", "Net pay"]}, {"q": "When spending is greater than income, a budget has a:", "options": ["Deficit", "Dividend", "Premium", "Surplus"]}, {"q": "Moving money to savings as soon as you are paid is called:", "options": ["Refinancing", "Paying yourself first", "Overdrafting", "Cosigning"]}, {"q": "Standard FDIC insurance covers deposits up to:", "options": ["2,500 dollars total", "250,000 dollars per depositor, per institution, per ownership category", "Nothing", "1 million dollars always"]}, {"q": "A warning sign of a scam is:", "options": ["Pressure to pay with gift cards right away", "A written contract you can read", "A call to a known number", "Time to compare"]}, {"q": "Interest calculated on principal plus past interest is:", "options": ["Simple interest", "Compound interest", "A tax", "A fee"]}, {"q": "Paying only the minimum on a credit card balance usually:", "options": ["Lowers the APR", "Raises your savings", "Clears the debt fast", "Costs much more in interest"]}, {"q": "The credit score factor with the greatest weight is:", "options": ["Your address", "Payment history", "Your age", "Your job title"]}, {"q": "The debt payoff method that targets the highest interest rate first is the:", "options": ["Balloon", "Avalanche", "Minimum", "Snowball"]}, {"q": "Spreading money across many investments to reduce risk is:", "options": ["Reconciliation", "Diversification", "Inflation", "Withholding"]}, {"q": "The amount you pay before insurance begins to pay is the:", "options": ["Deductible", "Dividend", "Premium", "Copay only"]}, {"q": "Revenue minus expenses equals:", "options": ["Penalty", "Profit", "Premium", "Principal"]}, {"q": "2 Corinthians 9:7 says God loveth a:", "options": ["Reluctant giver", "Hidden giver", "Cheerful giver", "Silent giver"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Personal Finance and Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,0,1,1,0,1,3,1,1,1,0,1,2}'::int[], array[$j$A steward manages for the owner.$j$,$j$Needs are required for life.$j$,$j$Net pay is take home pay.$j$,$j$A deficit means expenses exceed income.$j$,$j$Save before you spend.$j$,$j$That is the standard coverage limit.$j$,$j$Urgency and odd payment methods signal fraud.$j$,$j$That is compounding.$j$,$j$Interest keeps building.$j$,$j$Paying on time matters most.$j$,$j$The avalanche saves the most interest.$j$,$j$Do not put all your eggs in one basket.$j$,$j$A deductible is paid first.$j$,$j$That is profit.$j$,$j$God values a joyful heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Personal Finance and Stewardship$j$ on conflict (item_id) do nothing;
end
$seed$;
